from pathlib import Path
import sys
import time
import base64
import unittest
from unittest.mock import Mock
import cv2
import numpy as np
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
import completion_banner as banner
from capture_pipeline import PopupFrame
from recognition_session import RecognitionSession
import detector

class CompletionBannerTests(unittest.TestCase):
    def test_cyan_reference_at_720_1080_and_4k(self):
        # Lettering-only crop from the supplied recording; no player/game screen data.
        data=base64.b64decode('')
        colored=cv2.imdecode(np.frombuffer(data,np.uint8),cv2.IMREAD_COLOR)
        image=np.full((360,588,3),180,np.uint8)
        image[20:43,130:461]=colored
        for scale in (1.,1.5,3.):
            with self.subTest(scale=scale):
                self.assertIsNotNone(banner.find_completion_header(cv2.resize(image,None,fx=scale,fy=scale)))

    def test_blank_noise_and_other_cyan_banners_are_not_matches(self):
        for image in (np.zeros((360,588,3),np.uint8),np.random.default_rng(18).integers(0,256,(360,588,3),dtype=np.uint8)):
            self.assertIsNone(banner.find_completion_header(image))
        image=np.zeros((360,588,3),np.uint8)
        cv2.putText(image,'UAV READY',(140,70),cv2.FONT_HERSHEY_SIMPLEX,1.,(255,255,80),2)
        self.assertIsNone(banner.find_completion_header(image))
        self.assertFalse(banner.is_completion_text(['CHALLENGE IN PROGRESS']))

    def test_confirmed_completion_goes_to_review_once_without_unlock(self):
        messages=[];unlock=Mock(return_value=True)
        session=RecognitionSession(None,lambda *a,**kw:(['CHALLENGE COMPLETED','Get 15 player kills in a single match'],.95),
            detector.parse_candidate,lambda *a:None,messages.append,unlock,detector.non_camo_banner)
        frame=np.zeros((360,588,3),np.uint8)
        for at in (100.,101.):
            item=PopupFrame('center',frame,(.9,(130,20,330,22),'challenge'),time.monotonic(),'2026-10-29T01:00:00Z','test',at)
            result=session.process(item)
            self.assertEqual(result['reason'],'review-required')
        reviews=[m for m in messages if m['type']=='completion-review']
        self.assertEqual(len(reviews),1)
        self.assertTrue(reviews[0]['image'].startswith('data:image/jpeg;base64,'))
        unlock.assert_not_called()

    def test_header_without_confirmed_text_does_not_create_review(self):
        messages=[]
        session=RecognitionSession(None,lambda *a,**kw:(['UAV READY'],.99),lambda _:None,
            lambda *a:None,messages.append,Mock(),lambda _:False)
        session.process(PopupFrame('center',np.zeros((360,588,3),np.uint8),(.9,(130,20,330,22),'challenge'),time.monotonic(),'now','test'))
        self.assertFalse(any(m['type']=='completion-review' for m in messages))
